query workcenterHistory($workcenterId: String!, $transactionTypeId: String!) {
  workcenterHistory(where: {workcenterId: {_eq: $workcenterId}, transactionTypeId: {_eq: $transactionTypeId}}, first: 2, orderBy: {field: occurAt, direction: desc}) {
    edges {
      node {
        id
        workcenterId
        transactionTypeId
        duration
        shiftId
        occurAt
      }
    }
  }
}

